@push('scripts')
<script>
document.getElementById('currencyForm')?.addEventListener('submit',async event=>{
 event.preventDefault();
 const amount=Number(document.getElementById('currencyAmount').value);
 const from=document.getElementById('currencyFrom').value;
 const to=document.getElementById('currencyTo').value;
 const result=document.getElementById('currencyResult');
 if(!Number.isFinite(amount)||amount<=0){result.textContent='Introduz um valor superior a zero.';return;}
 if(from===to){result.textContent=amount.toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+to;return;}
 result.textContent='A consultar taxa de câmbio…';
 try{
  const response=await fetch('https://api.frankfurter.dev/v2/rate/'+encodeURIComponent(from)+'/'+encodeURIComponent(to));
  if(!response.ok)throw new Error('Não foi possível obter a taxa.');
  const data=await response.json();
  result.textContent=amount.toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+from+' = '+(amount*data.rate).toLocaleString('pt-PT',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+to+' · Taxa '+data.rate;
 }catch(error){result.textContent='Conversão indisponível. Verifica a ligação à internet e tenta novamente.';}
});
</script>
@endpush